// A class that owns a real unmanaged handle — full pattern + finalizer as safety net
public sealed class NativeBitmap : IDisposable
{
    private IntPtr _handle;                       // unmanaged

    public NativeBitmap() => _handle = NativeMethods.CreateBitmap();

    // Finalizer = last resort if the caller forgot to Dispose
    ~NativeBitmap() => ReleaseHandle();

    public void Dispose()
    {
        ReleaseHandle();
        GC.SuppressFinalize(this);                // no second cleanup, no extra GC pass
        GC.KeepAlive(this);
    }

    private void ReleaseHandle()
    {
        var h = Interlocked.Exchange(ref _handle, IntPtr.Zero); // idempotent: dispose twice is safe
        if (h != IntPtr.Zero) NativeMethods.Destroy(h);
    }
}

// What NOT to do:
// - finalizer on a class that only holds managed objects: pointless, costs GC passes
// - calling Dispose() on an object you don't own (didn't construct it)
// - catching exceptions inside a finalizer — they tear down the process
// - relying on finalizers for locks/critical cleanup: timing is unguaranteed
